mapper.select:
SELECT c.id AS chunkId, c.document_id AS documentId, doc.title AS documentTitle, c.section AS section, c.content AS content, word_similarity(#{keyword}, c.content) AS score FROM kb_chunk c JOIN kb_document doc ON doc.id = c.document_id WHERE word_similarity(#{keyword}, c.content) > #{minScore}
AND c.document_id = #{documentId}
ORDER BY score DESC, c.id LIMIT #{limit}

SELECT c.id AS chunkId, c.document_id AS documentId, doc.title AS documentTitle, c.section AS section, c.content AS content, 1.0 AS score FROM kb_chunk c JOIN kb_document doc ON doc.id = c.document_id WHERE c.content ILIKE CONCAT('%', #{keyword}, '%')
AND c.document_id = #{documentId}
ORDER BY c.id LIMIT #{limit}

mapper.update:
UPDATE kb_chunk
SET embedding = #{embedding}, embedding_model = #{model}
WHERE id = #{id}

mapper.select:
SELECT c.id AS chunkId, c.document_id AS documentId, doc.title AS documentTitle, c.section AS section, c.content AS content, c.embedding AS embedding FROM kb_chunk c JOIN kb_document doc ON doc.id = c.document_id WHERE c.embedding IS NOT NULL
AND c.document_id = #{documentId}
ORDER BY c.id LIMIT #{limit}
